package com.rulecraft.decisionops.expressions;

import com.rulecraft.decisionops.audit.AuditService;
import com.rulecraft.decisionops.catalog.CatalogService;
import com.rulecraft.decisionops.catalog.domain.DecisionServiceStatus;
import com.rulecraft.decisionops.expressions.domain.*;
import com.rulecraft.decisionops.expressions.language.ExpressionLanguage;
import com.rulecraft.decisionops.expressions.persistence.DecisionExpressionRepository;
import com.rulecraft.decisionops.graph.DecisionGraphService;
import com.rulecraft.decisionops.graph.DecisionGraphService.*;
import com.rulecraft.decisionops.graph.domain.*;
import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;
import com.rulecraft.decisionops.platform.web.DomainProblemException;
import com.rulecraft.decisionops.projects.ProjectAccessPolicy;
import com.rulecraft.decisionops.tables.persistence.DecisionTableRepository;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class DecisionExpressionService {
    private final DecisionExpressionRepository expressions;private final DecisionTableRepository tables;private final DecisionGraphService graphs;private final CatalogService catalog;
    private final ProjectAccessPolicy access;private final ExpressionLanguage language;private final AuditService audit;private final Clock clock;
    public DecisionExpressionService(DecisionExpressionRepository expressions,DecisionTableRepository tables,DecisionGraphService graphs,CatalogService catalog,ProjectAccessPolicy access,ExpressionLanguage language,AuditService audit,Clock clock){this.expressions=expressions;this.tables=tables;this.graphs=graphs;this.catalog=catalog;this.access=access;this.language=language;this.audit=audit;this.clock=clock;}
    @Transactional(readOnly=true)public Optional<ExpressionView> find(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID nodeId){var context=context(actor,projectId,serviceId,nodeId,false);return expressions.findByNodeIdAndTenantIdAndProjectId(nodeId,actor.tenantId(),projectId).map(value->view(value,context));}
    @Transactional(readOnly=true)public List<ExpressionSummary> summaries(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){var graph=graphs.get(actor,projectId,serviceId);return expressions.findAllByGraphIdAndTenantIdOrderByUpdatedAtDesc(graph.id(),actor.tenantId()).stream().map(value->{var node=graph.nodes().stream().filter(candidate->candidate.id().equals(value.getNodeId())&&candidate.kind()==GraphNodeKind.DECISION).findFirst();var status=ExpressionValidationStatus.INVALID;if(node.isPresent()){var inputs=node.get().ports().stream().filter(port->port.direction()==GraphPortDirection.INPUT).sorted(Comparator.comparingInt(GraphPortView::position)).toList();var output=node.get().ports().stream().filter(port->port.direction()==GraphPortDirection.OUTPUT).findFirst();if(output.isPresent()&&language.validate(value.getSourceText(),inputs,output.get()).valid())status=ExpressionValidationStatus.VALID;}return new ExpressionSummary(value.getNodeId(),status,value.getLanguageVersion(),value.getUpdatedAt(),value.getVersion());}).toList();}
    @Transactional public ExpressionView initialize(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID nodeId){var context=context(actor,projectId,serviceId,nodeId,true);if(expressions.existsByNodeId(nodeId))conflict("RC-EXPR-EXISTS","This decision already has an expression. Refresh to continue editing.");if(tables.existsByNodeId(nodeId))conflict("RC-IMPLEMENTATION-EXISTS","Remove the decision table before choosing an expression implementation.");var now=Instant.now(clock);var value=expressions.saveAndFlush(new DecisionExpressionDefinition(actor.tenantId(),projectId,context.graph().id(),nodeId,actor.userId(),now));audit.record(actor.tenantId(),actor.userId(),"DECISION_EXPRESSION_INITIALIZED","DECISION_EXPRESSION",value.getId(),Map.of("nodeId",nodeId,"language",ExpressionLanguage.VERSION));return view(value,context);}
    @Transactional public ExpressionView update(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID nodeId,ExpressionCommand command){var context=context(actor,projectId,serviceId,nodeId,true);var value=require(actor,projectId,nodeId);if(command==null||command.version()!=value.getVersion())conflict("RC-EXPR-STALE","The expression changed. Refresh before saving again.");var source=command.source()==null?"":command.source();if(source.length()>ExpressionLanguage.MAX_SOURCE)bad("RC-EXPR-SOURCE-LIMIT","Expressions can contain at most 12000 characters.");var validation=language.validate(source,context.inputs(),context.output());value.update(source,validation.valid()?ExpressionValidationStatus.VALID:ExpressionValidationStatus.INVALID,Instant.now(clock));expressions.saveAndFlush(value);audit.record(actor.tenantId(),actor.userId(),"DECISION_EXPRESSION_UPDATED","DECISION_EXPRESSION",value.getId(),Map.of("status",value.getValidationStatus().name(),"language",ExpressionLanguage.VERSION));return view(value,context);}
    @Transactional public void remove(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID nodeId,long version){context(actor,projectId,serviceId,nodeId,true);var value=require(actor,projectId,nodeId);if(version!=value.getVersion())conflict("RC-EXPR-STALE","The expression changed. Refresh before removing it.");var id=value.getId();expressions.delete(value);expressions.flush();audit.record(actor.tenantId(),actor.userId(),"DECISION_EXPRESSION_REMOVED","DECISION_EXPRESSION",id,Map.of("nodeId",nodeId));}
    private Context context(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID nodeId,boolean edit){if(edit)access.requireEdit(actor,projectId);else access.requireVisible(actor,projectId);var service=catalog.getService(actor,projectId,serviceId);if(edit&&service.status()!=DecisionServiceStatus.ACTIVE)conflict("RC-EXPR-SERVICE-ARCHIVED","Restore the decision service before authoring its expression.");var graph=graphs.get(actor,projectId,serviceId);var node=graph.nodes().stream().filter(value->value.id().equals(nodeId)).findFirst().orElseThrow(()->new DomainProblemException(HttpStatus.NOT_FOUND,"RC-GRAPH-NODE-NOT-FOUND","Decision node not found."));if(node.kind()!=GraphNodeKind.DECISION)bad("RC-EXPR-NODE-KIND","Expressions can attach only to decision nodes.");var inputs=node.ports().stream().filter(port->port.direction()==GraphPortDirection.INPUT).sorted(Comparator.comparingInt(GraphPortView::position)).toList();var output=node.ports().stream().filter(port->port.direction()==GraphPortDirection.OUTPUT).findFirst().orElseThrow();return new Context(graph,node,inputs,output);}
    private ExpressionView view(DecisionExpressionDefinition value,Context context){var validation=language.validate(value.getSourceText(),context.inputs(),context.output());return new ExpressionView(value.getId(),context.graph().id(),context.node().id(),context.node().nodeKey(),context.node().name(),value.getLanguageVersion(),value.getSourceText(),validation.valid()?ExpressionValidationStatus.VALID:ExpressionValidationStatus.INVALID,validation.issues(),validation.inferredType(),context.inputs().stream().map(port->new SymbolView(port.portKey(),port.label(),port.type())).toList(),new SymbolView(context.output().portKey(),context.output().label(),context.output().type()),value.getUpdatedAt(),value.getVersion());}
    private DecisionExpressionDefinition require(RuleCraftPrincipal actor,UUID projectId,UUID nodeId){return expressions.findByNodeIdAndTenantIdAndProjectId(nodeId,actor.tenantId(),projectId).orElseThrow(()->new DomainProblemException(HttpStatus.NOT_FOUND,"RC-EXPR-NOT-FOUND","This decision does not have an expression yet."));}
    private void bad(String code,String message){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}private void conflict(String code,String message){throw new DomainProblemException(HttpStatus.CONFLICT,code,message);}
    private record Context(GraphView graph,GraphNodeView node,List<GraphPortView> inputs,GraphPortView output){}
    public record ExpressionCommand(long version,String source){}
    public record SymbolView(String key,String label,TypeRefCommand type){}
    public record ExpressionView(UUID id,UUID graphId,UUID nodeId,String nodeKey,String nodeName,String languageVersion,String source,ExpressionValidationStatus validationStatus,List<ExpressionLanguage.Issue> issues,String inferredType,List<SymbolView> inputs,SymbolView output,Instant updatedAt,long version){}
    public record ExpressionSummary(UUID nodeId,ExpressionValidationStatus validationStatus,String languageVersion,Instant updatedAt,long version){}
}
